create table if not exists private.allowed_owners(email text primary key); alter table private.allowed_owners enable row level security; revoke all on private.allowed_owners from anon, authenticated; create or replace function private.assign_aircon_owner() returns trigger language plpgsql security definer set search_path = '' as $$ begin if new.email_confirmed_at is not null and exists (select 1 from private.allowed_owners where email = lower(new.email)) then update public.devices set owner_id = new.id where owner_id is null; end if; return new; end; $$; revoke all on function private.assign_aircon_owner() from public, anon, authenticated;
